<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreChequeRequest;
use App\Models\Cheque;
use App\Services\ChequeAccessService;
use App\Services\ChequeService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class ReceivedChequeController extends Controller { public function index(Request$r,ChequeAccessService$a){return $this->listing($r,$a,'received','Received Cheques');} public function create(){return view('cheques.form',$this->formData('received'));} public function store(StoreChequeRequest$r,ChequeService$s){$c=$s->create($r->validated(),$r->file('attachment'));return redirect()->route('cheques.show',$c)->with('success','Received cheque saved and moved to hold.');} private function listing($r,$a,$type,$title){$q=$a->scope(Cheque::with(['customer','supplier'])->where('cheque_type',$type),$r->user());app(\App\Http\Controllers\ChequeReportController::class)->filters($q,$r);$cheques=$q->orderBy('cheque_date')->paginate(25)->withQueryString();return view('cheques.index',compact('cheques','type','title'));} private function formData($type){return['type'=>$type,'customers'=>DB::table('customers')->whereNull('deleted_at')->orderBy('name')->get(),'suppliers'=>DB::table('suppliers')->whereNull('deleted_at')->orderBy('name')->get(),'sales'=>DB::table('sales')->orderByDesc('id')->limit(200)->get(),'purchases'=>DB::table('purchases')->orderByDesc('id')->limit(200)->get(),'accounts'=>DB::table('accounts')->where('status',true)->orderBy('account_name')->get(),'stores'=>DB::table('stores')->where('status',true)->get(),'lorries'=>DB::table('lorries')->whereNull('deleted_at')->get()];} public function show(Cheque$c,Request$r,ChequeAccessService$a){$a->authorize($c,$r->user());$c->load(['customer','supplier','sale','purchase','statusLogs.user']);return view('cheques.show',['cheque'=>$c]);} }
